// src/hooks/useTelegram.ts
import { useEffect, useRef } from 'react';
import { getTelegram } from '../telegram';

export function useExpandOnMount(): void {
  useEffect(() => {
    getTelegram()?.expand();
  }, []);
}

// Telegram owns back navigation: show/hide its BackButton and forward the
// click to in-app routing instead of drawing a second back arrow on screen.
export function useBackButton(onBack: () => void): void {
  const handlerRef = useRef(onBack);
  handlerRef.current = onBack;

  useEffect(() => {
    const tg = getTelegram();
    if (!tg) return;

    const handler = () => handlerRef.current();
    tg.BackButton.onClick(handler);
    tg.BackButton.show();

    return () => {
      tg.BackButton.offClick(handler);
      tg.BackButton.hide();
    };
  }, []);
}

interface MainButtonOptions {
  text: string;
  enabled: boolean;
  loading: boolean;
  onClick: () => void;
}

// The screen's one primary action lives in the host MainButton, not a
// page-drawn sticky footer, so it never duplicates or collides with the host UI.
export function useMainButton({ text, enabled, loading, onClick }: MainButtonOptions): void {
  const handlerRef = useRef(onClick);
  handlerRef.current = onClick;

  useEffect(() => {
    const tg = getTelegram();
    if (!tg) return;

    const handler = () => handlerRef.current();
    tg.MainButton.onClick(handler);
    tg.MainButton.show();

    return () => {
      tg.MainButton.offClick(handler);
      tg.MainButton.hide();
    };
  }, []);

  useEffect(() => {
    const tg = getTelegram();
    if (!tg) return;
    tg.MainButton.setText(text);
  }, [text]);

  useEffect(() => {
    const tg = getTelegram();
    if (!tg) return;
    if (loading) {
      tg.MainButton.showProgress(false);
    } else {
      tg.MainButton.hideProgress();
      if (enabled) tg.MainButton.enable();
      else tg.MainButton.disable();
    }
  }, [enabled, loading]);
}

// Arms the host's closing confirmation while the form has unsaved input, so a
// swipe-down to close the Mini App doesn't silently discard it.
export function useClosingConfirmation(dirty: boolean): void {
  useEffect(() => {
    const tg = getTelegram();
    if (!tg) return;
    if (dirty) tg.enableClosingConfirmation();
    else tg.disableClosingConfirmation();

    return () => tg.disableClosingConfirmation();
  }, [dirty]);
}

export function hapticSuccess(): void {
  getTelegram()?.HapticFeedback.notificationOccurred('success');
}

export function hapticError(): void {
  getTelegram()?.HapticFeedback.notificationOccurred('error');
}
