```tsx
// src/components/CheckoutScreen.tsx
import React, { useMemo, useState } from 'react';
import { CartItem, DeliveryAddress, AddressErrors } from '../types';
import { getTelegram } from '../telegram';
import {
  useExpandOnMount,
  useBackButton,
  useMainButton,
  useClosingConfirmation,
  hapticSuccess,
  hapticError,
} from '../hooks/useTelegram';
import './CheckoutScreen.css';

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  city: '',
  street: '',
  apartment: '',
  zipCode: '',
  comment: '',
};

function validate(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (address.fullName.trim().length < 2) {
    errors.fullName = 'Enter your full name';
  }
  if (!/^\+?[0-9\s-]{7,15}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number';
  }
  if (address.city.trim().length < 2) {
    errors.city = 'Enter a city';
  }
  if (address.street.trim().length < 3) {
    errors.street = 'Enter a street address';
  }
  if (!/^[A-Za-z0-9\s-]{3,10}$/.test(address.zipCode.trim())) {
    errors.zipCode = 'Enter a valid ZIP / postal code';
  }

  return errors;
}

function formatPrice(value: number): string {
  return new Intl.NumberFormat(undefined, { style: 'currency', currency: 'USD' }).format(value);
}

interface CheckoutScreenProps {
  cartItems: CartItem[];
  onBack: () => void;
  onPay: (address: DeliveryAddress) => Promise<void>;
}

export default function CheckoutScreen({ cartItems, onBack, onPay }: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const isTelegram = getTelegram() !== null;

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0),
    [cartItems],
  );
  const deliveryFee = subtotal > 0 ? 4.99 : 0;
  const total = subtotal + deliveryFee;

  const errors = useMemo(() => validate(address), [address]);
  const isValid = Object.keys(errors).length === 0 && cartItems.length > 0;
  const isDirty = Object.values(address).some((value) => value.trim().length > 0);

  useExpandOnMount();
  useBackButton(onBack);
  useClosingConfirmation(isDirty && !submitting);

  function markAllTouched() {
    setTouched({
      fullName: true,
      phone: true,
      city: true,
      street: true,
      apartment: true,
      zipCode: true,
      comment: true,
    });
  }

  async function handlePay() {
    if (submitting) return;
    if (!isValid) {
      markAllTouched();
      hapticError();
      return;
    }

    setSubmitting(true);
    setSubmitError(null);
    try {
      await onPay(address);
      hapticSuccess();
    } catch {
      hapticError();
      setSubmitError('Payment failed. Please try again.');
    } finally {
      setSubmitting(false);
    }
  }

  useMainButton({
    text: `Pay ${formatPrice(total)}`,
    enabled: isValid,
    loading: submitting,
    onClick: handlePay,
  });

  function updateField<K extends keyof DeliveryAddress>(field: K, value: DeliveryAddress[K]) {
    setAddress((prev) => ({ ...prev, [field]: value }));
  }

  function handleBlur(field: keyof DeliveryAddress) {
    setTouched((prev) => ({ ...prev, [field]: true }));
  }

  return (
    <div className="checkout-screen">
      {!isTelegram && (
        <button type="button" className="fallback-back" onClick={onBack}>
          ‹ Back to cart
        </button>
      )}

      <h1 className="checkout-title">Checkout</h1>

      <section className="section" aria-label="Cart items">
        <h2 className="section-heading">Your order</h2>
        <ul className="cart-list">
          {cartItems.map((item) => (
            <li key={item.id} className="cart-item">
              {item.imageUrl ? (
                <img className="item-thumb" src={item.imageUrl} alt={item.name} />
              ) : (
                <div className="item-thumb item-thumb-placeholder" aria-hidden="true" />
              )}
              <div className="item-info">
                <span className="item-name">{item.name}</span>
                <span className="item-qty">Qty {item.quantity}</span>
              </div>
              <span className="item-price">{formatPrice(item.quantity * item.unitPrice)}</span>
            </li>
          ))}
          {cartItems.length === 0 && <li className="cart-empty">Your cart is empty.</li>}
        </ul>

        <div className="summary">
          <div className="summary-row">
            <span>Subtotal</span>
            <span>{formatPrice(subtotal)}</span>
          </div>
          <div className="summary-row">
            <span>Delivery</span>
            <span>{formatPrice(deliveryFee)}</span>
          </div>
          <div className="summary-row summary-total">
            <span>Total</span>
            <span>{formatPrice(total)}</span>
          </div>
        </div>
      </section>

      <section className="section" aria-label="Delivery address">
        <h2 className="section-heading">Delivery address</h2>
        <form className="address-form" noValidate onSubmit={(e) => e.preventDefault()}>
          <div className="form-group">
            <label className="form-label" htmlFor="fullName">Full name</label>
            <input
              id="fullName"
              className="form-input"
              type="text"
              autoComplete="name"
              value={address.fullName}
              onChange={(e) => updateField('fullName', e.target.value)}
              onBlur={() => handleBlur('fullName')}
            />
            {touched.fullName && errors.fullName && (
              <span className="error-text">{errors.fullName}</span>
            )}
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="phone">Phone number</label>
            <input
              id="phone"
              className="form-input"
              type="tel"
              autoComplete="tel"
              value={address.phone}
              onChange={(e) => updateField('phone', e.target.value)}
              onBlur={() => handleBlur('phone')}
            />
            {touched.phone && errors.phone && <span className="error-text">{errors.phone}</span>}
          </div>

          <div className="form-row">
            <div className="form-group">
              <label className="form-label" htmlFor="city">City</label>
              <input
                id="city"
                className="form-input"
                type="text"
                autoComplete="address-level2"
                value={address.city}
                onChange={(e) => updateField('city', e.target.value)}
                onBlur={() => handleBlur('city')}
              />
              {touched.city && errors.city && <span className="error-text">{errors.city}</span>}
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="zipCode">ZIP / Postal code</label>
              <input
                id="zipCode"
                className="form-input"
                type="text"
                autoComplete="postal-code"
                value={address.zipCode}
                onChange={(e) => updateField('zipCode', e.target.value)}
                onBlur={() => handleBlur('zipCode')}
              />
              {touched.zipCode && errors.zipCode && (
                <span className="error-text">{errors.zipCode}</span>
              )}
            </div>
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="street">Street address</label>
            <input
              id="street"
              className="form-input"
              type="text"
              autoComplete="address-line1"
              value={address.street}
              onChange={(e) => updateField('street', e.target.value)}
              onBlur={() => handleBlur('street')}
            />
            {touched.street && errors.street && <span className="error-text">{errors.street}</span>}
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="apartment">Apartment / suite (optional)</label>
            <input
              id="apartment"
              className="form-input"
              type="text"
              autoComplete="address-line2"
              value={address.apartment}
              onChange={(e) => updateField('apartment', e.target.value)}
            />
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="comment">Delivery notes (optional)</label>
            <textarea
              id="comment"
              className="form-textarea"
              rows={3}
              value={address.comment}
              onChange={(e) => updateField('comment', e.target.value)}
            />
          </div>
        </form>

        {submitError && <p className="submit-error" role="alert">{submitError}</p>}
      </section>

      {/* Spacer so content never sits under the host's bottom bar / MainButton */}
      <div className="bottom-spacer" aria-hidden="true" />
    </div>
  );
}
